package net.officefloor.hq.app.rollup;

import jakarta.persistence.EntityManager;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.asof.SheetHistory;
import net.officefloor.hq.app.setting.SheetParentLink;
import net.officefloor.hq.app.setting.SheetParentRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The figures of a sheet's descendants (its children, the sheets naming it as their parent, then
 * theirs, and so on), added up: the number of people on them and each one's due-total and
 * overdue-total as that sheet shows it. The screen adds the sheet's own figures to make its
 * consolidated figures. A sheet with no children has none. The sheet's own figures are answered too, as
 * it shows them. Read as of a date (within the as-of view's transaction, which is rolled back), every
 * sheet of the tree is put back to how it stood at the end of that day, with that date as its today.
 */
@Service
public class ConsolidatedService {

    /** The descendants, in the order found (nearest first), and their figures added up, and the sheet's own;
     *  the totals with two decimals. */
    public record Descendants(List<String> sheets, int peopleCount, String dueTotal, String overdueTotal,
            int ownPeopleCount, String ownDueTotal, String ownOverdueTotal) {
    }

    private final SheetParentRepository parents;
    private final Rollup rollup;
    private final SheetHistory history;
    private final EntityManager entityManager;

    public ConsolidatedService(SheetParentRepository parents, Rollup rollup, SheetHistory history,
            EntityManager entityManager) {
        this.parents = parents;
        this.rollup = rollup;
        this.history = history;
        this.entityManager = entityManager;
    }

    /** The descendants as the store holds them now, or with the date, as every sheet of the tree stood at
     *  the end of that day: only within a transaction that is rolled back (the as-of view's). */
    @Transactional(readOnly = true)
    public Descendants descendantsOf(String sheetId, LocalDate asOf) {
        Set<String> found = asOf == null ? descendantsNow(sheetId) : descendantsAsOf(sheetId, asOf);
        int peopleCount = 0;
        BigDecimal due = BigDecimal.ZERO;
        BigDecimal overdue = BigDecimal.ZERO;
        for (String sheet : found) {
            Rollup.Snapshot figures = rollup.snapshot(sheet);
            peopleCount += figures.people().size();
            due = due.add(figures.dueTotal());
            overdue = overdue.add(figures.overdueTotal());
        }
        Rollup.Snapshot own = rollup.snapshot(sheetId);
        return new Descendants(new ArrayList<>(found), peopleCount, text(due), text(overdue), own.people().size(),
                text(own.dueTotal()), text(own.overdueTotal()));
    }

    private Set<String> descendantsNow(String sheetId) {
        Set<String> found = new LinkedHashSet<>();
        Deque<String> next = new ArrayDeque<>(List.of(sheetId));
        while (!next.isEmpty()) {
            for (SheetParentLink child : parents.findByParentId(next.pop())) {
                if (!child.getSheetId().equals(sheetId) && found.add(child.getSheetId())) next.add(child.getSheetId());
            }
        }
        return found;
    }

    /** Each sheet naming a sheet of the tree as its parent is put back to the date, and is a descendant
     *  when, as it stood then, it named that sheet. */
    private Set<String> descendantsAsOf(String sheetId, LocalDate asOf) {
        Set<String> found = new LinkedHashSet<>();
        Set<String> restored = new LinkedHashSet<>(List.of(sheetId));
        Deque<String> next = new ArrayDeque<>(List.of(sheetId));
        while (!next.isEmpty()) {
            String parent = next.pop();
            for (String child : history.childrenOf(parent)) {
                if (found.contains(child) || child.equals(sheetId)) continue;
                if (restored.add(child)) history.restoreWithParents(child, asOf);
                if (history.namesParent(child, parent)) {
                    found.add(child);
                    next.add(child);
                }
            }
        }
        // The store was put back beneath the persistence context: what it holds is read afresh.
        entityManager.clear();
        return found;
    }

    private static String text(BigDecimal figure) {
        return figure.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }
}
package net.officefloor.hq.app.rollup;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.List;
import net.officefloor.hq.app.asof.AsOf;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets")
@Validated
public class ConsolidatedController {

    private final ConsolidatedService service;
    private final TreeSearchService search;

    public ConsolidatedController(ConsolidatedService service, TreeSearchService search) {
        this.service = service;
        this.search = search;
    }

    /** The figures of the sheet's descendants added up; the screen adds its own to consolidate them. Read
     *  from a screen set to an as-of date, every sheet of the tree as it stood at the end of that day. */
    @GetMapping("/{id}/descendants")
    public ConsolidatedService.Descendants descendants(@PathVariable @NotBlank @Size(max = 100) String id,
            HttpServletRequest request) {
        return service.descendantsOf(id.trim(), AsOf.of(request).orElse(null));
    }

    /** The people over the sheet's tree whose name or an alias contains the text, case ignored. */
    @GetMapping("/{id}/tree-search")
    public List<TreeSearchService.Found> treeSearch(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestParam(defaultValue = "") @Size(max = 200) String text) {
        return search.search(id.trim(), text);
    }
}
import { Component, computed, effect, inject, input, signal } from '@angular/core';
import { FigurePipe } from '../../core/figure.pipe';
import { Session } from '../../core/session';
import { cents, money } from '../claims/claims-api';
import { ConsolidatedApi, DescendantsView } from './consolidated-api';

// The consolidated figures over the sheet and all its descendants (the sheets naming it as their
// parent, then theirs, and so on): the number of people, and each sheet's due-total and overdue-total
// as that sheet shows it, added up. The sheet's own figures are those it shows; its descendants' are
// re-read each time a sheet is loaded. A sheet with no children shows its own figures. While the screen
// shows the sheet as of a date, the consolidated figures are as of that date too: every sheet of the
// tree as it stood at the end of that day, with that date as its today.
@Component({
  selector: 'app-consolidated',
  imports: [FigurePipe],
  template: `
    <section aria-label="Consolidated figures" data-testid="consolidated">
      <dl>
        <dt>People (with descendants)</dt>
        <dd data-testid="consolidated-people-count">{{ peopleCount() }}</dd>
        <dt>Due (with descendants)</dt>
        <dd data-testid="consolidated-due-total">{{ dueTotal() | figure }}</dd>
        <dt>Overdue (with descendants)</dt>
        <dd data-testid="consolidated-overdue-total">{{ overdueTotal() | figure }}</dd>
      </dl>
    </section>
  `,
})
export class Consolidated {
  private readonly session = inject(Session);
  private readonly api = inject(ConsolidatedApi);

  /** The sheet's own figures, as it shows them. */
  readonly ownPeopleCount = input.required<number>();
  readonly ownDueTotal = input.required<string>();
  readonly ownOverdueTotal = input.required<string>();

  /** The loaded sheet's descendants' figures; null until read (or when the read failed). */
  private readonly descendants = signal<DescendantsView | null>(null);

  /** The sheet's own figures, as it shows them. */
  private readonly own = computed(() =>
    ({ peopleCount: this.ownPeopleCount(), dueTotal: this.ownDueTotal(), overdueTotal: this.ownOverdueTotal() }));

  protected readonly peopleCount = computed(() => this.own().peopleCount + (this.descendants()?.peopleCount ?? 0));
  protected readonly dueTotal = computed(() =>
    money(cents(this.own().dueTotal) + cents(this.descendants()?.dueTotal ?? '0.00')));
  protected readonly overdueTotal = computed(() =>
    money(cents(this.own().overdueTotal) + cents(this.descendants()?.overdueTotal ?? '0.00')));

  constructor() {
    effect(() => {
      // A new sheet view each time a sheet is loaded, so its descendants are read again.
      const sheet = this.session.sheet();
      this.descendants.set(null);
      if (sheet === null) return;
      this.api.descendants(sheet.id).then(
        (view) => { if (this.session.sheet() === sheet) this.descendants.set(view); },
        () => undefined);
    });
  }
}
import { HttpClient, HttpContext } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { LIVE_READ } from '../../core/as-of.interceptor';

/** A sheet's descendants (its children, then theirs, and so on) and their figures added up. */
export interface DescendantsView {
  sheets: string[];
  peopleCount: number;
  /** Each descendant's due-total as that sheet shows it, added up, with two decimals. */
  dueTotal: string;
  /** Each descendant's overdue-total as that sheet shows it, added up, with two decimals. */
  overdueTotal: string;
  /** The sheet's own figures as it shows them now. */
  ownPeopleCount: number;
  ownDueTotal: string;
  ownOverdueTotal: string;
}

// The figures of a sheet's descendants, and its own: while the screen shows the sheet as of a date, every
// sheet of the tree as it stood at the end of that day.
@Injectable({ providedIn: 'root' })
export class ConsolidatedApi {
  private readonly http = inject(HttpClient);

  descendants(sheetId: string): Promise<DescendantsView> {
    return firstValueFrom(this.http.get<DescendantsView>(`/api/sheets/${encodeURIComponent(sheetId)}/descendants`));
  }
}

/** A person found over a sheet's tree: their sheet, name and due-total (two decimals, or n/a). */
export interface TreeSearchHit {
  sheetId: string;
  name: string;
  dueTotal: string;
}

// The people over a sheet's tree whose name or an alias contains the text, case ignored: the sheet's
// own first in list order, then the other sheets' by sheet id. Read live, as the store holds them now.
@Injectable({ providedIn: 'root' })
export class TreeSearchApi {
  private readonly http = inject(HttpClient);

  search(sheetId: string, text: string): Promise<TreeSearchHit[]> {
    return firstValueFrom(this.http.get<TreeSearchHit[]>(`/api/sheets/${encodeURIComponent(sheetId)}/tree-search`,
      { params: { text }, context: new HttpContext().set(LIVE_READ, true) }));
  }
}
