      const due = claimOwedCents(c, this.ratesOn(person, c.date), this.floor.centsOn(c.date), this.lateness(), this.claims()) ?? 0;
      const was = by.get(c.personId) ?? { upTo30: 0, upTo60: 0, over60: 0 };
